# Verify my rule: 6s in complete horizontal or vertical lines become 2s
def transform(demo, value_to_find=6, value_to_replace=2):
    rows, cols = len(demo), len(demo[0])
    complete_rows = set()
    complete_cols = set()

    # Find all complete rows/columns of value_to_find
    for r in range(rows):
        if all(demo[r][c] == value_to_find for c in range(cols)):
            complete_rows.add(r)
    for c in range(cols):
        if all(demo[r][c] == value_to_find for r in range(rows)):
            complete_cols.add(c)

    # Apply transformation
    result = []
    for r in range(rows):
        row = []
        for c in range(cols):
            if demo[r][c] == value_to_find and (r in complete_rows or c in complete_cols):
                row.append(value_to_replace)
            else:
                row.append(demo[r][c])
        result.append(row)
    return result

